// TwistedPixel's script interpreters (src/twistedpixel/script). The expected values are golden values of the port's
// own results, taken once a private harness had found every one of them identical to Windows' engines as
// TwistedPixel.dll hosts them (vbscript.dll, and jscript9Legacy.dll for JScript). They guard against regressions.
// Values are VARIANTs printed as type:hex-bits ("5:3fe57e2e6ea85448" is a Double, "8:..." a String, an "E<n>" string
// the runtime error a statement raised under On Error Resume Next).
//
// GROUPS holds 1178 such cases from our own probe scripts (operators over every VARIANT type, conversions,
// number formatting, literals, Rnd, statements, comparisons). Cases whose result goes through sin/cos/atan/exp/log/pow
// are left out: script/libm.ts uses Math.*, which can differ from the C runtime in the last bit.
import { describe, expect, it } from 'vitest';
import { compileScript, ScriptError, tpTrue, type HostMember, type ScriptHost, VbArray } from '../src/twistedpixel/script/index';

/** a few of TwistedPixel's members, with the semantics TwistedPixel.dll gives them */
function tinyHost(): ScriptHost & { vals: Float32Array; log: string[] } {
  const members: HostMember[] = [
    { name: 'tp_zoom', kind: 'prop', vt: 4 },
    { name: 'tp_Script', kind: 'put', vt: 8, params: [] },
    { name: 'above', kind: 'method', vt: 4, params: [4, 4] },
    { name: 'iif', kind: 'method', vt: 4, params: [4, 4, 4] },
    { name: 'min', kind: 'method', vt: 4, params: [4, 4] },
    { name: 'tp_TextureWidth', kind: 'method', vt: 2, params: [] },
    { name: 'tp_rot', kind: 'prop', vt: 4 },
    { name: 'tp_NextPreset', kind: 'put', vt: 8, params: [] },
  ];
  const vals = new Float32Array(members.length);
  vals[0] = 1;
  const log: string[] = [];
  return {
    members, vals, log,
    get: (i) => vals[i] ?? 0,
    set: (i, v, vt) => { vals[i] = v; log.push(`${members[i]!.name}=${v} [${vt}]`); },
    call: (i, a, vts) => {
      const x = a[0] as number, y = a[1] as number, z = a[2] as number;
      log.push(`${members[i]!.name}(${a.join(',')}) [${vts.join(',')}]`);
      switch (members[i]!.name) {
        case 'above': return Math.fround(x > y ? 1 : 0);
        case 'iif': return x === 0 || x !== x ? z : y;
        case 'min': return x < y || x !== x || y !== y ? x : y;
        case 'tp_TextureWidth': return 512;
      }
      return undefined;
    },
  };
}

const F32 = new Float32Array(1), U32 = new Uint32Array(F32.buffer), F64 = new Float64Array(1), U64 = new BigUint64Array(F64.buffer);
const hex = (n: number, w: number) => (n >>> 0).toString(16).padStart(w, '0').slice(-w);
function varText(vt: number, v: unknown): string {
  if (vt >= 0x2000) {
    const a = v as VbArray;
    if (a.ub.length === 0) return '[|]';
    return '[' + a.ub.slice().reverse().map((u, d, arr) => String(u + 1) + (d + 1 < arr.length ? 'x' : '|')).join('') +
      Array.from({ length: a.size }, (_, k) => varText(a.t[k]!, a.t[k] === 8 || a.t[k]! >= 0x2000 ? a.o[k] : a.n[k])).join(',') + ']';
  }
  switch (vt) {
    case 0: return '0:';
    case 1: return '1:';
    case 2: case 11: return `${vt}:${hex((v as number) & 0xffff, 4)}`;
    case 3: case 10: return `${vt}:${hex(v as number, 8)}`;
    case 4: F32[0] = v as number; return '4:' + hex(U32[0]!, 8);
    case 17: return '17:' + hex(v as number, 2);
    case 8: return `8:"${v as string}"`;
    default: F64[0] = v as number; return `${vt}:` + U64[0]!.toString(16).padStart(16, '0');
  }
}

