describe('VBScript, case by case', () => {
  for (const g of GROUPS) {
    it(g.name, () => {
      const s = compileScript(g.src, 'vbscript', tinyHost());
      s.call('PresetInitialize');
      const r = s.globals().get('r')!.v as VbArray;
      const bad: string[] = [];
      for (const [k, want] of Object.entries(g.want)) {
        const got = varText(r.t[+k]!, r.t[+k] === 8 || r.t[+k]! >= 0x2000 ? r.o[+k] : r.n[+k]);
        if (got !== want) bad.push(`r(${k}) want ${want} got ${got}`);
      }
      expect(bad).toEqual([]);
    });
  }
});

function vbs(body: string, host = tinyHost()) {
  const s = compileScript(body, 'vbscript', host);
  return { s, host, run: () => s.call('PresetInitialize') };
}

describe('VBScript and the host', () => {
  it('raises a runtime error as an exception with number, description and the statement position', () => {
    const { run } = vbs('Dim x\nSub PresetInitialize()\n  x = 1\n    x = x / 0\nEnd Sub\n');
    try { run(); expect.unreachable(); } catch (e) {
      expect(e).toBeInstanceOf(ScriptError);
      const se = e as ScriptError;
      expect([se.number, se.description, se.line, se.col, se.scode.toString(16)]).toEqual([11, 'Division by zero', 3, 4, '800a000b']);
      expect([se.source, se.wCode, se.lineText]).toEqual(['Microsoft VBScript runtime error', 0, null]);
    }
  });
  it('names the function, array, host member or value in the error description', () => {
    const desc = (stmt: string) => {
      try { vbs(`Dim a(3), d()\nSub PresetInitialize()\n ${stmt}\nEnd Sub\n`).run(); } catch (e) { return (e as ScriptError).description; }
      return '';
    };
    expect(['x = Log(-1)', 'x = log(0) + Log(1)', 'x = CInt(40000)', 'x = Abs("abcdefghijklmnopqrstuvwxyz")', 'x = a(5.5)',
      'x = a(1, 2)', 'x = d(5)', 'x = min("q", 1)', 'x = min(1)', 'Foo 1', 'x = Sgn(Null)', 'x = 1 / 0'].map(desc)).toEqual([
      "Invalid procedure call or argument: 'Log'", "Invalid procedure call or argument: 'log'", "Overflow: 'CInt'",
      'Type mismatch: \'[string: "abcdefghijklmnopqrst"]\'', "Subscript out of range: '[number: 5.5]'", "Subscript out of range: 'a'",
      "Subscript out of range: 'd'", "Type mismatch: 'min'", "Wrong number of arguments or invalid property assignment: 'min'",
      "Type mismatch: 'Foo'", 'Invalid use of Null', 'Division by zero']);
  });
  it('rejects a syntax error at compile time', () => {
    try { compileScript('Sub PresetInitialize(\nEnd Sub\n', 'vbscript', tinyHost()); expect.unreachable(); } catch (e) {
      const se = e as ScriptError;
      expect([se instanceof ScriptError, se.syntax, se.source, se.line, se.lineText]).toEqual([true, true, 'Microsoft VBScript compilation error', 0, 'Sub PresetInitialize(']);
    }
  });
  it('stores into TwistedPixel variables the way its dispatch does', () => {
    const { run, host } = vbs('Sub PresetInitialize()\n tp_zoom = True\n tp_rot = 0.1\n tp_zoom = "2.5"\n tp_Script = 3\nEnd Sub\n');
    run();
    // True stores +1.0 (TwistedPixel negates VARIANT_BOOL); a Double is rounded to float; a String is converted;
    // a 'put' member receives its argument converted to its declared type
    expect(host.log).toEqual(['tp_zoom=1 [11]', `tp_rot=${Math.fround(0.1)} [5]`, 'tp_zoom=2.5 [8]', 'tp_Script(3) [2]']);
  });
  it('resolves host names case-sensitively, by the first spelling of the name in the script', () => {
    const { run } = vbs('Option Explicit\nSub PresetInitialize()\n Dim a\n a = TP_ZOOM\nEnd Sub\n');
    expect(run).toThrow(/Variable is undefined/);
  });
  it('restarts Rnd for every engine (each preset)', () => {
    const src = 'Dim a\nSub PresetInitialize()\n a = Rnd\nEnd Sub\n';
    const a = vbs(src), b = vbs(src);
    a.run(); a.run(); b.run();
    expect(varText(4, b.s.globals().get('a')!.v)).toBe('4:3f349ec3');
    expect(varText(4, a.s.globals().get('a')!.v)).toBe('4:3f088e7a');
  });
  it('reads True from ProcessWaveform only for a result whose low 16 bits are all ones', () => {
    const { s } = vbs('Function ProcessWaveform()\n ProcessWaveform = tp_zoom = 1\nEnd Function\nFunction ProcessCustomShape()\n ProcessCustomShape = -1.0\nEnd Function\n');
    expect(tpTrue(s.call('ProcessWaveform'))).toBe(true);
    expect(tpTrue(s.call('ProcessCustomShape'))).toBe(false);
  });
});

describe('JScript', () => {
  const run = (body: string, random?: number) => {
    const host = tinyHost();
    if (random !== undefined) host.random = () => random;
    const s = compileScript(body, 'jscript', host);
    return { r: s.call('f'), log: host.log };
  };
  it('passes Long or Double to TwistedPixel as jscript does', () => {
    const { log } = run('var a = 1, b = 3;\nfunction f() {\n tp_zoom = 20.0; tp_zoom = 2.5; tp_zoom = 20.0 + Math.round(10 * Math.random());\n' +
      ' tp_zoom = 3.0 / 1.5; tp_zoom = 6 / 3; tp_zoom = a / b; tp_zoom = 6 * 0.5; tp_zoom = 2147483647 + 1; tp_zoom = -0;\n' +
      ' tp_zoom = -a; tp_zoom = Math.round(-0.4); tp_zoom = Math.sin(0); tp_zoom = 1e3; tp_zoom = 0x10; tp_zoom += 0.5; tp_NextPreset = "";\n}\n', 0.7);
    expect(log.map((l) => l.slice(l.lastIndexOf('['))).join(' ')).toBe('[3] [5] [3] [5] [3] [5] [5] [5] [5] [3] [5] [5] [3] [3] [5] [8]');
    expect(log[2]).toBe('tp_zoom=27 [3]');
  });
  it('computes in doubles, rounding Math.round half up', () => {
    const v = (e: string) => { const { r } = run(`var a = 1, b = 3, c = 0.1, d = 0.2;\nfunction f() { return ${e}; }\n`); return varText(r.vt, r.v); };
    expect([v('a / b'), v('c + d'), v('c * d'), v('Math.round(2.5)'), v('Math.round(-2.5)'), v('1 + 1.1102230246251568e-16 * (1 + 2.220446049250313e-16)')])
      .toEqual(['5:3fd5555555555555', '5:3fd3333333333334', '5:3f947ae147ae147c', '3:00000003', '3:fffffffe', '5:3ff0000000000001']);
  });
});
